<?php $page_title='Prescription';require_once __DIR__.'/../includes/header.php';$p=$pdo->query("SELECT id,name FROM patients ORDER BY name")->fetchAll();$d=$pdo->query("SELECT id,name FROM doctors ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO prescriptions(patient_id,doctor_id,prescription_date,medicine,dosage,duration,instructions) VALUES(?,?,?,?,?,?,?)")->execute([$_POST['patient_id'],$_POST['doctor_id'],$_POST['prescription_date'],$_POST['medicine'],$_POST['dosage'],$_POST['duration'],$_POST['instructions']]);header('Location:index.php');exit;}?><h2>New Prescription</h2><div class="card p-4 mt-3"><form method="post"><div class="row g-3"><div class="col-md-6"><label>Patient</label><select name="patient_id" class="form-select"><?php foreach($p as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Doctor</label><select name="doctor_id" class="form-select"><?php foreach($d as $x):?><option value="<?=$x['id']?>">Dr. <?=e($x['name'])?></option><?php endforeach;?></select></div><?php foreach(['medicine'=>'Medicine','dosage'=>'Dosage','duration'=>'Duration','instructions'=>'Instructions'] as $n=>$l):?><div class="col-md-6"><label><?=$l?></label><input name="<?=$n?>" class="form-control" required></div><?php endforeach;?><div class="col-md-6"><label>Date</label><input type="date" name="prescription_date" value="<?=date('Y-m-d')?>" class="form-control"></div></div><button class="btn btn-primary mt-3">Save Prescription</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>